// Example of a simple LazyColumn with items
@Composable
fun MyLazyList(messages: List<String>) {
    // LazyColumn is used for vertically scrolling lists
    LazyColumn {
        // Add a single header item
        item {
            Text("Message List Header")
        }

        // Add multiple items from a list
        items(messages) { message ->
            // For each message in the list, display a Text composable
            // Add some padding using a modifier
            Text(message, modifier = Modifier.padding(8.dp))
        }

        // Add another single item, maybe a footer
        item {
            Text("End of Messages")
        }
    }
}

