// Example of a clickable item
@Composable
fun MyClickableItem(text: String, onClickAction: () -> Unit) {
    Text(
        text = text,
        // Apply the clickable modifier
        // and also some padding for spacing
        modifier = Modifier
            .clickable(onClick = onClickAction) // Add click behavior
            .padding(16.dp) // Add space around the text
    )
}
