// Let's assume you have a data class for your items
data class MyItemData(val id: Int, val text: String, val imageUrl: String)

@Composable
fun InteractiveItemList(items: List<MyItemData>, onItemClick: (MyItemData) -> Unit) {
    // We use LazyColumn for performance with potentially large lists
    LazyColumn {
        // Add each item from the list
        // We can use the item's ID as a key for better performance/animations
        // Let's also add contentType for composition reuse optimization
        items(
            items = items,
            key = { it.id }, // Using ID as a unique key
            contentType = { "MyItemType" } // Providing a content type
        ) { item ->
            // This block defines the UI for each item in the list
            // We can use a Row to place the image and text side-by-side
            Row(
                // Add modifiers to the whole item row
                modifier = Modifier
                    .fillMaxWidth() // Make the row take up the full width available
                    .clickable { onItemClick(item) } // Make the entire row clickable
                    .padding(12.dp), // Add some padding around the item [30]
                verticalAlignment = Alignment.CenterVertically // Vertically align image and text in the center
            ) {
                // Display the image for the item
                // (Assuming MyImageItem from the example above, requires external library)
                // MyImageItem(imageUrl = item.imageUrl)

                // If not using AsyncImage, you'd load a local drawable like this:
                // import androidx.compose.foundation.Image
                // import androidx.compose.ui.res.painterResource
                // Image(
                //     painter = painterResource(id = R.drawable.your_placeholder_image), // Replace with actual drawable
                //     contentDescription = item.text, // Accessibility for the image
                //     modifier = Modifier.size(64.dp) // Size modifier
                // )

                // Add some horizontal space between the image and the text
                Spacer(modifier = Modifier.padding(horizontal = 8.dp)) // Add padding specifically on horizontal sides

                // Display the text for the item
                Text(
                    text = item.text,
                    // Use a modifier to give the text weight so it fills the remaining space
                    // Weight requires being in a RowScope or ColumnScope
                    modifier = Modifier.weight(1f)
                )
            }
        }
    }
}
